// Original synthesized arena sounds. No downloaded audio or speech dependency.
export class GladiatorAudio{
 constructor({muted=()=>false,music=.15,sfx=.5}={}){this.muted=muted;this.music=music;this.sfx=sfx;this.ctx=null;this.timer=null;this.notes=0;}
 init(){try{this.ctx||=new (window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{});}catch{} }
 tone(freq,duration=.14,type='triangle',volume=.25,slide=0){if(!this.ctx||this.muted())return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(Math.max(20,freq),c.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(25,freq+slide),c.currentTime+duration);g.gain.setValueAtTime(.001,c.currentTime);g.gain.exponentialRampToValueAtTime(Math.max(.001,volume*this.sfx),c.currentTime+.015);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+duration+.02);}
 noise(duration=.2,volume=.3,cutoff=1000){if(!this.ctx||this.muted())return;const c=this.ctx,b=c.createBuffer(1,Math.ceil(c.sampleRate*duration),c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=b;f.type='lowpass';f.frequency.value=cutoff;g.gain.value=volume*this.sfx;s.connect(f).connect(g).connect(c.destination);s.start();}
 play(kind){if(['quick','normal','power','charge'].includes(kind))this.noise(kind==='power'?.35:.15,.3,kind==='power'?600:4000);else if(kind==='block'){this.tone(880,.23,'square',.12,-170);this.tone(1320,.16,'sine',.13);}else if(kind==='impact'||kind==='shove'){this.noise(.2,.5,380);this.tone(110,.17,'sawtooth',.2,-60);}else if(kind==='rest')this.tone(280,.4,'sine',.15,80);else if(kind==='taunt'){this.tone(170,.3,'sawtooth',.12,70);this.noise(.3,.1,700);}else if(kind==='victory'){for(const [i,n]of [262,330,392,523].entries())setTimeout(()=>this.tone(n,.3,'triangle',.3),i*130);this.noise(.8,.2,1700);}else if(kind==='defeat'){this.tone(220,.6,'triangle',.23,-140);this.noise(.5,.16,500);}else if(kind==='coin'){this.tone(1400,.15,'sine',.2);this.tone(1800,.22,'sine',.12);}else if(kind==='jumpForward'||kind==='jumpBack')this.tone(150,.2,'triangle',.2,250);else{this.noise(.08,.18,500);}}
 startMusic(){if(this.timer)return;this.timer=setInterval(()=>{if(!this.ctx||this.muted()||!this.music)return;const old=this.sfx;this.sfx=this.music;const melody=[196,247,294,392,330,294,247,220];this.tone(melody[this.notes++%melody.length],.38,'triangle',.25);if(this.notes%4===0)this.tone(98,.6,'sine',.15);this.sfx=old;},440);}
 pause(){clearInterval(this.timer);this.timer=null;this.ctx?.suspend().catch(()=>{});}
 dispose(){clearInterval(this.timer);this.timer=null;this.ctx?.close().catch(()=>{});this.ctx=null;}
}
